import{_ as e,o as r,c as o,a3 as a}from"./chunks/framework.BTQ4eCVb.js";const p=JSON.parse('{"title":"Short Links — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Short Links — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/short-links"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Short Links — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/short-links"}]]},"headers":[],"relativePath":"user-guide/short-links.md","filePath":"user-guide/short-links.md","lastUpdated":1787503667000}'),i={name:"user-guide/short-links.md"};function s(n,t,d,l,c,h){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="short-links-—-user-guide" tabindex="-1">Short Links — User Guide <a class="header-anchor" href="#short-links-—-user-guide" aria-label="Permalink to &quot;Short Links — User Guide&quot;">​</a></h1><h2 id="install-the-module" tabindex="-1">Install the module <a class="header-anchor" href="#install-the-module" aria-label="Permalink to &quot;Install the module&quot;">​</a></h2><p><strong>Short Links</strong> is a free Marketplace module. Install it from <strong>Marketplace → Operations</strong> before creating links.</p><h2 id="who-can-use-short-links" tabindex="-1">Who can use Short Links <a class="header-anchor" href="#who-can-use-short-links" aria-label="Permalink to &quot;Who can use Short Links&quot;">​</a></h2><p>Your workspace must have the <strong>Short Links</strong> module installed. Your role needs the relevant permissions:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Allows</th></tr></thead><tbody><tr><td><code>view</code></td><td>List and open short links</td></tr><tr><td><code>create</code></td><td>Create new links</td></tr><tr><td><code>update</code></td><td>Edit links</td></tr><tr><td><code>delete</code> / <code>restore</code> / <code>force.delete</code></td><td>Trash lifecycle</td></tr><tr><td><code>view_analytics</code></td><td>Click stats on the record page</td></tr></tbody></table><h2 id="list" tabindex="-1">List <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List&quot;">​</a></h2><p>Open <strong>Short Links</strong> from the sidebar (Operations).</p><ul><li>Search by title or destination URL</li><li>Filter by status (Active / Paused) and trash state when you can restore</li><li>KPI cards show total links, active links, and total clicks</li><li>Copy a short URL from the row menu</li></ul><h2 id="create-edit" tabindex="-1">Create &amp; edit <a class="header-anchor" href="#create-edit" aria-label="Permalink to &quot;Create &amp; edit&quot;">​</a></h2><ol><li>Click <strong>New short link</strong> (shortcut: <code>n</code> when the list is focused and you have create permission)</li><li>Enter a destination URL (required) and optional title, status, expiry, and UTM parameters</li><li>Save — EloSync generates a public short URL on <code>https://go.elosync.com/r/{code}</code> (7-character code). Your operator may use a different short domain via <code>SHORT_LINK_BASE_URL</code>.</li></ol><p>Edit from the row menu or the record page. Focus search with <code>Ctrl/⌘+F</code>.</p><h2 id="record-page" tabindex="-1">Record page <a class="header-anchor" href="#record-page" aria-label="Permalink to &quot;Record page&quot;">​</a></h2><ul><li><strong>Details</strong> — destination, status, expiry, copyable short URL</li><li><strong>Analytics</strong> (requires <code>view_analytics</code>) — total clicks, clicks by day, top referrers, device breakdown</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td>Active</td><td>Redirects visitors to the destination URL</td></tr><tr><td>Paused</td><td>Redirect returns not found; link remains editable</td></tr></tbody></table><p>Expired links (past <strong>Expires at</strong>) also stop redirecting.</p><h2 id="public-redirects" tabindex="-1">Public redirects <a class="header-anchor" href="#public-redirects" aria-label="Permalink to &quot;Public redirects&quot;">​</a></h2><p>Visitors open the short URL without signing in. Clicks are recorded asynchronously (bots are redirected but not counted). UTM parameters configured on the link are appended to the destination URL on redirect.</p>',19)])])}const m=e(i,[["render",s]]);export{p as __pageData,m as default};
